56	    method,
57	    headers: {
58	      ...(body !== undefined || rawBody !== undefined ? { 'content-type': 'application/json' } : {}),
59	      ...headers,
60	    },
61	    body: rawBody ?? (body !== undefined ? JSON.stringify(body) : undefined),
62	  });
63	  const text = await response.text();
64	  return {
65	    status: response.status,
66	    etag: response.headers.get('etag'),
67	    body: text ? JSON.parse(text) : null,
68	  };
69	}
