84	    assert.equal(empty.status, 200);
85	    assert.deepEqual(empty.body, []);
86	    assert.match(empty.etag, ETAG_PATTERN);
87	    assert.equal(empty.etag, (await request(server.url, 'GET', '/documents')).etag);
88	
89	    const et = empty.etag;
90	    await request(server.url, 'POST', '/documents', {
91	      body: { id: 'a', title: 'A', body: 'body', tags: ['Zeta', 'beta', 'beta'] },
92	      headers: { 'if-match': et },
93	    });
94	    let current = (await request(server.url, 'GET', '/documents')).etag;
95	    await request(server.url, 'POST', '/documents', {
96	      body: { id: 'b', title: 'B', body: 'body', tags: ['beta', 'alpha'] },
97	      headers: { 'if-match': current },
98	    });
99	    current = (await request(server.url, 'GET', '/documents')).etag;
100	    await request(server.url, 'POST', '/documents', {
101	      body: { id: 'c', title: 'C', body: 'body', tags: [] },
102	      headers: { 'if-match': current },
103	    });
104	
105	    const tags = await request(server.url, 'GET', '/tags');
106	    assert.equal(tags.status, 200);
107	    assert.deepEqual(tags.body, [
108	      { tag: 'alpha', count: 1 },
109	      { tag: 'beta', count: 2 },
110	      { tag: 'zeta', count: 1 },
111	    ]);
112	    assert.match(tags.etag, ETAG_PATTERN);
113	
114	    // Deleting the only user of a tag drops it and updates counts immediately.
115	    current = (await request(server.url, 'GET', '/documents')).etag;
116	    await request(server.url, 'DELETE', '/documents/b', { headers: { 'if-match': current } });
117	    const after = await request(server.url, 'GET', '/tags');
118	    assert.deepEqual(after.body, [
119	      { tag: 'beta', count: 1 },
120	      { tag: 'zeta', count: 1 },
121	    ]);
122	  } finally {
123	    await server.stop();
124	  }
125	});
