      throw new SnapshotError('INVALID_SNAPSHOT', `duplicate document id: ${document.id}`);
    }
    if (titles.has(document.title)) {
      throw new SnapshotError('INVALID_SNAPSHOT', `duplicate normalized title: ${document.title}`);
