    assert.equal(response.status, 200);
    const documents = docMap(response.body);
    assert.deepEqual(documents.get('a').title, 'B');
    assert.equal(documents.get('a').body, 'offline a');
    assert.deepEqual(documents.get('b').title, 'A');
